-- Keys MUST match the `drillId` values in apps/ml-worker/src/biomech2d.py's
-- DRILLS dict exactly — that dict is what analysis results actually reference
-- (via drill_suggestions.drill_key), and approveSuggestion() looks up this
-- table by that same key. A mismatch here means every drill lookup silently
-- returns undefined and cues/rationale go missing from every calendar event —
-- see apps/api/src/db/__tests__/referenceDrillKeys.test.ts, which asserts
-- these stay in sync.
--
-- `recovery_phases` carries a research-backed, TIME-BASED 4-phase corrective
-- program from the offline biomechanics research pipeline
-- (apps/api/scripts/research/generate-metric-biomechanics.ts). Every athlete
-- who gets this metric's flaw progresses through the SAME ordered phases
-- (Stability -> Strength -> Plyometrics & Movement -> Back to Sport) — this
-- is not a difficulty tier picked by athlete level, it's a recovery
-- timeline. Empty until a metric has been run through the pipeline AND
-- human-reviewed — see metric_biomechanics.sql. `[]` is not "no content yet
-- was written", it's "no reviewed content exists yet" — approveSuggestion()
-- must not treat an empty array as an error, just as "fall back to the flat
-- dosing" (generateDrillProgram(), not generateRecoveryProgram()).
INSERT INTO reference_drills (key, name, description, video_url, cues, contraindications, target_metrics, recovery_phases) VALUES
('drill-wall-drive', 'Wall drives', 'Static wall drive for acceleration mechanics and trunk-angle control', 'https://cdn.stride.ai/drills/wall-drives.mp4', '["Hold a long line from ankle to head","Resist bending at the waist","Drive knee up under control"]', '["lower_back_pain"]', '["trunk_lean"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":5,"exercises":[{"name":"Dead bug","sets":3,"reps":"8-12/side","cue":"Neutral spine, posterior pelvic tilt, exhale fully, move slowly","rationale":"Foundational motor control for both failure directions before any directional loading.","sourceCitation":"McGill motor-control philosophy"},{"name":"Bird dog","sets":3,"reps":"6-8/side, 8-10s hold","cue":"Reach long, keep hips level, avoid rotation or lumbar sag","rationale":"McGill Big 3 staple; builds anti-rotation/anti-extension control underlying both trunk-lean failure directions.","sourceCitation":"McGill Big 3"}],"advanceCriteria":"Completes all sets with no compensatory rotation, lumbar sag, or breath-holding across 2 sessions."},{"phase":2,"name":"Strength","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":4,"exercises":[{"name":"Side bridge / plank","sets":3,"reps":"7-10s/side, building up","cue":"Stack hips and shoulders in a line; no hip sag or rotation","rationale":"Anti-flexion/anti-lateral-flexion strength directly opposing the excessive-lean failure direction.","sourceCitation":"McGill Big 3"},{"name":"Wall drill / wall march","sets":3,"reps":"5-6 marches/leg or 5s holds","cue":"Lean as a straight line from the ankle, not the waist; drive knee under control","rationale":"Trains hip-hinge/postural lean from the ankle, giving too-upright athletes the capacity for adequate lean without over-flexing.","sourceCitation":"Standard sprint-technique coaching cue"}],"advanceCriteria":"Bilateral side-bridge holds reach target duration; wall drill shows a consistent straight ankle-to-shoulder line under cue."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":2,"exercises":[{"name":"Light resisted sled march","sets":5,"reps":"10-15m","cue":"Drive from the hip with the ankle-hinge lean pattern from Phase 2; light load only","rationale":"Impact-tolerance and postural-loading bridge toward running-relevant demand. (Note: no dedicated eccentric quad/calf-Achilles protocol was found for the impact-attenuation gap — this substitutes as a bridge, not a full replacement.)","sourceCitation":"Light postural sled-loading protocol, 10-20% BM"}],"advanceCriteria":"Tolerates sled load with no compensatory postural collapse or pain; trunk angle during marching approximates the target band."},{"phase":4,"name":"Back to Sport","durationWeeksMin":4,"durationWeeksMax":8,"daysPerWeek":3,"exercises":[{"name":"Trunk-flexion gait retraining with visual feedback (too-upright athletes)","sets":1,"reps":"Structured 4-week program, 2-3x/week, integrated into running","cue":"Increase forward lean during running using real-time visual/verbal feedback until retained without cueing","rationale":"Directly retrains correct trunk angle at running-relevant velocity for athletes on the too-upright side.","sourceCitation":"Teng et al. 2020, Phys Ther Sport: +10.1 deg trunk flexion, -17.8% PFJ stress by week 8"},{"name":"Anti-flexion core maintenance (excessive-lean athletes)","sets":2,"reps":"Maintenance dose, 2x/week","cue":"Hold the Phase 2 trunk position as fatigue and volume increase","rationale":"Prevents fatigue-driven drift into injurious excess forward lean during return to running.","sourceCitation":"McGill Big 3 maintenance dosing"}],"advanceCriteria":"Trunk flexion consistently sits within the healthy band (phase-appropriate) without active cueing under full training volume."}]'),
('drill-high-knee-switch', 'High-knee wall switches', 'High-knee marching drill for knee drive improvement', 'https://cdn.stride.ai/drills/high-knee-switch.mp4', '["Punch the knee up to hip height, toe up","Quick switch, minimal ground contact","Stay tall through hips"]', '["knee_pain","hip_flexor_strain"]', '["knee_drive"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":2,"exercises":[{"name":"A-skip / high-knee drill","sets":3,"reps":"15-20m","cue":"Focus on rhythm and ground-contact timing, not maximizing knee height","rationale":"Coordination only, explicitly NOT the primary power stimulus — evidence does not show A-skip performance predicts sprint time.","sourceCitation":"Coordination drill; caveat per contested front-side-mechanics evidence"}],"advanceCriteria":"Consistent rhythm and no compensation across sessions — indicates readiness for loading, not that mechanics are \"trained.\""},{"phase":2,"name":"Strength","durationWeeksMin":6,"durationWeeksMax":8,"daysPerWeek":3,"exercises":[{"name":"Standing banded/cable hip flexion (leg pull-through)","sets":3,"reps":"12-15/leg","cue":"Control the movement through full range, no momentum swinging","rationale":"The evidence-based backbone — the one exercise with direct RCT support (strength AND sprint-time improvement).","sourceCitation":"Deane et al. 2005 JSCR RCT: +12.2% hip flexion strength, -3.8% 20m sprint time"}],"advanceCriteria":"Completes 8-week block with measurable hip flexor strength improvement."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":4,"durationWeeksMax":6,"daysPerWeek":2,"exercises":[{"name":"Ankle-loaded high-knee march","sets":4,"reps":"8-10/leg","cue":"Deliberate, controlled tempo, light ankle load","rationale":"Best mechanistic support for hip-flexion power tied to step frequency; dosing extrapolated from a test protocol, not a training study.","sourceCitation":"Nagahara & Murata 2020, dosing extrapolated"},{"name":"Complex hip flexor training (resisted + unresisted contrast)","sets":4,"reps":"6-8/leg resisted + 10-15m unresisted","cue":"Resisted march with intent, then transfer immediately into an unresisted sprint segment","rationale":"Contrast pairing for rate of force development; single-study support, offered as plausible not settled.","sourceCitation":"2011 rugby league complex-training study"}],"advanceCriteria":"Tolerates the contrast pairing without form breakdown or excess fatigue."},{"phase":4,"name":"Back to Sport","durationWeeksMin":2,"durationWeeksMax":4,"daysPerWeek":3,"exercises":[{"name":"General sprint-specific loading (acceleration/flying sprints, sled work)","sets":4,"reps":"3-6 x 20-40m efforts","cue":"Coach overall sprint quality and rhythm — do not cue conscious thigh-angle maximizing","rationale":"Given the contested front-side-mechanics narrative, front-side gains are allowed to emerge as a byproduct of general sprint loading rather than being chased directly.","sourceCitation":"General sprint-integration principle, framed against Haralabidis 2022 and Haugen 2018"},{"name":"Standing banded hip flexion (maintenance)","sets":3,"reps":"12-15/leg, 2x/week","cue":"Same tempo as Phase 2","rationale":"Maintains the one RCT-backed strength gain through return to sprinting.","sourceCitation":"Deane et al. 2005, maintenance dosing"}],"advanceCriteria":"Full participation in sprint training; hip flexor strength maintained at or above Phase 2 levels."}]'),
('drill-dribble-bound', 'Dribble-to-bound build-ups', 'Progressive bounding drill for full hip extension at toe-off', 'https://cdn.stride.ai/drills/dribble-bound.mp4', '["Feel the back leg finish long behind you","Full hip extension, not a cyclical action","Maintain flat back"]', '["hamstring_strain","hip_labrum_tear"]', '["hip_extension"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":5,"exercises":[{"name":"Half-kneeling hip flexor stretch","sets":3,"reps":"45-60s holds/side","cue":"Posterior pelvic tilt, squeeze the back glute, ribs stacked over pelvis","rationale":"Addresses the range-limiting factor and the hip-flexor-tightness -> LBP pathway; goes first before loading.","sourceCitation":"JOSPT RCT; J Sports Sci 2025 footballer LBP study"},{"name":"Couch stretch","sets":2,"reps":"60s holds/side","cue":"Back knee down, drive hip forward, pelvis tucked","rationale":"Deeper end-range hip flexor/quad extensibility, same mobility category.","sourceCitation":"Standard PT dosing"},{"name":"Dead bug (low dose)","sets":2,"reps":"8/side, slow tempo","cue":"Low back flat, no rib flare","rationale":"Establishes isometric pelvis/trunk control before loading — targets the Schuermans/Kenneally-Dabrowski pathway at its most foundational form.","sourceCitation":"Schuermans et al. 2017 mechanistic basis"}],"advanceCriteria":"Pain-free full-range stretches both sides; dead bug with no low-back arch or pelvic rotation."},{"phase":2,"name":"Strength","durationWeeksMin":3,"durationWeeksMax":4,"daysPerWeek":3,"exercises":[{"name":"Glute bridge, bilateral -> single-leg","sets":3,"reps":"10-12 reps, 3-5s squeeze","cue":"Drive through heels, squeeze glutes hard at lockout","rationale":"Real loading backbone — builds hip-extensor force capacity for active extension at toe-off.","sourceCitation":"Distefano 2009, Boren 2011 EMG"},{"name":"Single-leg RDL (bodyweight)","sets":3,"reps":"3/leg, up to 6x/week","cue":"Hinge at hip, flat line head-to-heel","rationale":"Loads hip extensors through a single-leg, sprint-relevant range; direct HSI-risk-reduction cohort study.","sourceCitation":"Otani et al. 2025 IJSPT"},{"name":"Half-kneeling hip flexor stretch (maintenance)","sets":2,"reps":"45-60s/side, 3x/week","cue":"Same form as Phase 1","rationale":"Preserves range gained in Phase 1 — strength loading alone does not maintain mobility.","sourceCitation":"Carried forward from Phase 1"}],"advanceCriteria":"Single-leg bridge and RDL for full reps with a level, stable pelvis."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":4,"durationWeeksMax":6,"daysPerWeek":3,"exercises":[{"name":"Barbell/banded hip thrust","sets":3,"reps":"6-10 @ 60-84% 1RM","cue":"Chin tucked, drive through mid-foot to full extension, no lumbar overextension","rationale":"Heaviest, most direct hip-extensor loading stimulus once base strength/pelvis control is established.","sourceCitation":"PMC11745155, PMC10593473"},{"name":"Nordic hamstring curl","sets":2,"reps":"progressive 1-2x5 -> 3x6-8","cue":"Control the lowering as long as possible","rationale":"Matches Chumanov late-swing hamstring-stretch timing directly; minimum effective dose 6-10 weeks, carries into Phase 4.","sourceCitation":"Injury-prevention literature, 6-10 week minimum"},{"name":"Single-leg RDL (loaded)","sets":3,"reps":"6-10/leg","cue":"Add load once bodyweight form is solid","rationale":"Progresses Phase 2 pattern to running-relevant load.","sourceCitation":"Otani et al. 2025 IJSPT"},{"name":"Pallof press, standing/dynamic","sets":3,"reps":"8-12/side","cue":"Press out from chest, resist rotation, stay tall","rationale":"Progresses pelvis control from isometric (Phase 1) to dynamic, sprint-relevant level.","sourceCitation":"Schuermans et al. 2017 mechanistic basis"}],"advanceCriteria":"Hip thrust and loaded SLRDL progressing without form breakdown; Nordic curl at 3x6-8; standing Pallof press with no trunk rotation."},{"phase":4,"name":"Back to Sport","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":2,"exercises":[{"name":"Hip thrust (maintenance)","sets":3,"reps":"10-15 banded, 1-2x/week","cue":"Same lockout quality as Phase 3","rationale":"Maintains hip-extensor strength while running volume returns.","sourceCitation":"Maintenance dosing"},{"name":"Nordic curl (maintenance)","sets":2,"reps":"6-8, 2x/week","cue":"Same form as Phase 3","rationale":"Completes the 6-10 week effective-dose window that began in Phase 3.","sourceCitation":"Injury-prevention literature"},{"name":"Integrated sprint-specific patterning (dribble-to-bound build-ups)","sets":3,"reps":"6-8 x 15-20m","cue":"Feel the back leg finish long and fully extended, not a cyclical cut-off","rationale":"Closes the proxy-metric gap — none of the cited studies measured Stride''s exact trunk-thigh angle, so isolated gains must be integrated into the actual sprint pattern.","sourceCitation":"Pipeline synthesis; no RCT dosing exists for this proxy-metric gap"}],"advanceCriteria":"Running volume back to baseline with no symptom recurrence over 2+ weeks; re-measure hip_extension against 160-185 deg band."}]'),
('drill-heel-recovery', 'Heel-to-butt A-skips', 'Extended A-skip drill for swing-leg knee flexion and recovery speed', 'https://cdn.stride.ai/drills/heel-recovery.mp4', '["Snap the heel up under your glute as the knee drives","Cycle through full range of motion","Maintain upright posture"]', '["knee_pain"]', '["knee_flexion"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":2,"exercises":[{"name":"A-skip","sets":2,"reps":"10-20m","cue":"Quick, light contacts; knee to hip height without overreaching","rationale":"Low-load coordination entry — targets movement quality, not the angle itself, since peak angle has not been shown to predict speed or injury risk.","sourceCitation":"Standard sprint-coaching entry drill, general practice"}],"advanceCriteria":"Consistent rhythm, no compensatory lean or asymmetry across 2 sessions."},{"phase":2,"name":"Strength","durationWeeksMin":6,"durationWeeksMax":8,"daysPerWeek":3,"exercises":[{"name":"Isotonic/machine-resisted hip flexion","sets":3,"reps":"8-12/leg","cue":"Controlled concentric drive and eccentric return, no lumbar substitution","rationale":"Evidence-based backbone — strengthens the actual mechanistic driver (hip flexors), not the knee angle directly.","sourceCitation":"Deane et al. 2005 JSCR RCT: +12.2% strength, -3.8% 40yd sprint time"},{"name":"B-skip","sets":2,"reps":"10-20m","cue":"Extend and paw back after knee drive","rationale":"Adds the flexor-to-extensor transition pattern on top of base coordination.","sourceCitation":"Standard sprint-coaching progression drill"}],"advanceCriteria":"8 weeks of progressive hip-flexion loading complete; clean B-skip mechanics at moderate speed."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":3,"durationWeeksMax":4,"daysPerWeek":2,"exercises":[{"name":"Band-resisted high-knee march/run with contrast set","sets":4,"reps":"12-15s resisted + 12-15s unresisted","cue":"Tall posture and quick cadence through resisted phase, let cadence release unresisted","rationale":"Bridges strength to running-relevant demand via contrast loading; general swing-mechanics/rhythm work, not a proven angle-correcting exercise.","sourceCitation":"General contrast-training principle, not metric-specific RCT evidence"},{"name":"A-skip / B-skip progression","sets":3,"reps":"10-20m","cue":"Faster cadence, maintain form under fatigue","rationale":"Continued coordination progression.","sourceCitation":"Standard sprint-coaching progression drills"}],"advanceCriteria":"Full contrast sets tolerated with no cadence drop-off; clean skip mechanics near full speed."},{"phase":4,"name":"Back to Sport","durationWeeksMin":4,"durationWeeksMax":6,"daysPerWeek":2,"exercises":[{"name":"Heavy sled push/sprint (30-50% BM)","sets":5,"reps":"15-20m","cue":"Strong hip extension, controlled recovery mechanics","rationale":"Integrates hip-flexor strength and coordination into running-specific output; maintenance/integration, not confirmation a specific deficit was corrected.","sourceCitation":"PMC12771950: 8-week RCT, heavy sled loading"},{"name":"A-skip (maintenance)","sets":2,"reps":"10-20m","cue":"Light, crisp reps as a check-in","rationale":"Low-load maintenance during return to sport.","sourceCitation":"Standard maintenance drill"}],"advanceCriteria":"Integrates sled work into full sessions without breakdown; no swing-phase discomfort reported."}]'),
('drill-arm-iso', 'Seated arm-drive isolation', 'Isolated arm mechanics drill for front-to-back arm swing', 'https://cdn.stride.ai/drills/arm-iso.mp4', '["Drive elbows straight back, hands cheek-to-hip","Don''t cross the midline","Relax the hands"]', '[]', '["arm_swing"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":3,"exercises":[{"name":"Standing/kneeling isolated arm action drill","sets":3,"reps":"10-15s per position","cue":"Drive elbow straight back, relaxed hand, minimal trunk involvement","rationale":"Lowest-complexity entry — isolates the shoulder-driven pattern before speed/coordination demands are added.","sourceCitation":"Koo et al. 2025 elbow-angle work; coaching-literature isolation drill"}],"advanceCriteria":"Holds a consistent 70-110 deg elbow angle in both positions across all sets without cueing."},{"phase":2,"name":"Strength","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":3,"exercises":[{"name":"Seated arm-drive drill","sets":4,"reps":"20-30s","cue":"Drive front-to-back through a fixed elbow angle at increasing tempo","rationale":"Reinforces front-to-back drive pattern. Evidence base is thin — coaching-literature staple, contested by some coaches as teaching an unrealistically fixed angle. Use as pattern-building, not literal target.","sourceCitation":"Coaching literature, contested, thin evidence base"},{"name":"Straight-arm running (awareness drill)","sets":3,"reps":"20-30m","cue":"Run with elbows locked straight, then contrast immediately with normal arm action","rationale":"Builds kinesthetic awareness of what elbow-driven action contributes to running mechanics.","sourceCitation":"Coaching literature, thin evidence base"}],"advanceCriteria":"Consistent front-to-back drive at increasing tempo; clear felt contrast between straight-arm and normal action."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":3,"exercises":[{"name":"Fast Arms drill (frequency overload)","sets":4,"reps":"15-20s","cue":"Maximize swing frequency while holding elbow angle steady","rationale":"Overloads swing frequency to build rate capacity underlying faster stride cycling.","sourceCitation":"Coaching literature, thin evidence base, contrast-pair drill"},{"name":"Big Arms drill (amplitude overload)","sets":3,"reps":"15-20s","cue":"Maximize front-to-back range while holding elbow angle steady","rationale":"Counterpart to the frequency drill — gives a felt sense of the rate/range trade-off, without asserting more amplitude is inherently better (per Lang et al. 2023).","sourceCitation":"Coaching literature, thin evidence base; amplitude caveat per Lang et al. 2023"}],"advanceCriteria":"Executes both variants with stable elbow angle, no compensatory trunk rotation, near-maximal effort."},{"phase":4,"name":"Back to Sport","durationWeeksMin":2,"durationWeeksMax":4,"daysPerWeek":2,"exercises":[{"name":"Half-and-half arms (contralateral integration run)","sets":2,"reps":"30-40m","cue":"Run at speed with normal arm action, smooth symmetric drive integrated with full-body mechanics — not forcing a fixed angle","rationale":"Integrates the isolated skill into full sprinting, closing the loop from Phase 1. Individualized-calibration applies directly: reinforce the athlete''s own efficient pattern rather than one ''ideal'' amplitude for everyone.","sourceCitation":"Coaching literature; calibration constraint per Lang et al. 2023"}],"advanceCriteria":"Maintains relaxed, symmetric drive at full sprint speed over repeated reps without conscious cueing."}]'),
('drill-quick-feet', 'Quick-feet + cadence intervals', 'Rapid ground-contact drill to reduce overstride and braking impulse', 'https://cdn.stride.ai/drills/quick-feet.mp4', '["Land the foot under your hip, not out in front","Quicker, lighter steps","Minimal ground contact time"]', '["ankle_sprain","plantar_fasciitis"]', '["overstride"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":3,"exercises":[{"name":"Supervised gait-retraining introduction","sets":1,"reps":"1 instructional session + 4-6 independent runs over 2 weeks","cue":"Take slightly quicker, lighter steps; land closer under the hips","rationale":"Introduces the pattern under supervision before independent practice, low load.","sourceCitation":"One-session gait-retraining protocol, novice/recreational variant"}],"advanceCriteria":"Reproduces the cued pattern unsupervised without discomfort or form breakdown."},{"phase":2,"name":"Strength","durationWeeksMin":6,"durationWeeksMax":6,"daysPerWeek":3,"exercises":[{"name":"Metronome-cued cadence increase","sets":1,"reps":"+5-10% above baseline cadence, full run duration, cueing faded near the end","cue":"Match foot strikes to the beat; think quicker/shorter, not longer reach","rationale":"The one intervention with actual causal evidence for reducing overstride-related loading.","sourceCitation":"Heiderscheit et al. 2011; Bramah et al. 2019 RCT"}],"advanceCriteria":"Sustains +5-10% cadence for full run duration without conscious cueing."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":3,"durationWeeksMax":4,"daysPerWeek":2,"exercises":[{"name":"Wicket/hurdle runs","sets":5,"reps":"8-10 hurdles, spacing below natural stride length","cue":"Quick, light contacts through each hurdle","rationale":"Forces reduced reach and faster turnover under externally imposed spacing.","sourceCitation":"Practitioner consensus, no dedicated RCT"},{"name":"Quick-feet agility ladder drills","sets":4,"reps":"15-20s","cue":"Fast, light contacts, minimal dwell time","rationale":"Adjunct reactive-turnover stimulus; lowest-confidence tier, used for movement variety only.","sourceCitation":"Practitioner consensus, adjunct only"}],"advanceCriteria":"Maintains quicker-cadence pattern through hurdle spacing and ladder work; overstride trending into healthy band."},{"phase":4,"name":"Back to Sport","durationWeeksMin":12,"durationWeeksMax":12,"daysPerWeek":5,"exercises":[{"name":"Progressive structured cadence overload","sets":1,"reps":"+7.5% cadence, sustained across all training runs","cue":"Carry the higher cadence as the new default, not just drill work","rationale":"Integrates corrected cadence into full training volume for durable, long-term adaptation.","sourceCitation":"Wang et al. 2020, PeerJ"}],"advanceCriteria":"Overstride consistently within 0-12% across regular training runs; cadence increase maintained without conscious effort."}]'),
('drill-wickets', 'Wicket runs', 'Stride length and frequency drill with low hurdles to reduce vertical bounce', 'https://cdn.stride.ai/drills/wicket-runs.mp4', '["Run tall and flat","Push horizontally, minimise bounce","Consistent stride pattern over the wickets"]', '["hamstring_tightness"]', '["vertical_oscillation"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":3,"exercises":[{"name":"Pogo jumps / ankle hops","sets":3,"reps":"15-30s (~15-20 contacts)","cue":"Stiff ankles, minimal knee bend, quick light contacts","rationale":"Lowest-impact entry building basic elastic capacity; framed as economy foundation, not rehab.","sourceCitation":"Markovic & Mikulic 2010 review"},{"name":"Skipping drills (A-skip)","sets":3,"reps":"20-30m","cue":"Light quick contacts, tall posture","rationale":"Coordinative entry point, also seeds the Phase 4 cadence lever.","sourceCitation":"Turner et al. 2003: RE improved 2-3%"}],"advanceCriteria":"Quiet, consistent ground contacts, no next-day soreness."},{"phase":2,"name":"Strength","durationWeeksMin":2,"durationWeeksMax":4,"daysPerWeek":3,"exercises":[{"name":"Bounding / single-leg bounding","sets":4,"reps":"15-30m","cue":"Full hip extension, quick active landing, cover ground","rationale":"Builds underlying tissue stiffness; two source studies directly link this dose to measured RE gains.","sourceCitation":"Saunders et al. 2006 JSCR (+4.1% RE); Spurrs et al. 2003 (+6.7% RE)"},{"name":"Isometric calf/Achilles and hip-extensor holds","sets":3,"reps":"30-45s holds","cue":"Gradual tension build, sustainable position","rationale":"Tissue-stiffness backbone alongside bounding. No specific cited exercise/dosing found for this — generic isometric practice used, not an invented citation.","sourceCitation":"Not specified in source literature — generic isometric-strength practice, flagged gap"}],"advanceCriteria":"Bounding at full prescribed distance with consistent contact quality; isometric holds at full duration."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":3,"exercises":[{"name":"Hurdle hops / repeated bilateral hops","sets":4,"reps":"5-10 hops over 15-30cm","cue":"Reactive, minimal contact time, quick rebound","rationale":"Higher-intensity reactive stimulus at sufficient weekly frequency for RE improvement.","sourceCitation":"Dudagoitia Barrio et al. 2023 meta-analysis: 3x/week threshold"},{"name":"Depth jumps / drop jumps (20-40cm)","sets":3,"reps":"5-8","cue":"Step off, land soft, explode immediately into next rep","rationale":"Highest-intensity stimulus, sequenced after the Phase 2 strength base.","sourceCitation":"Markovic & Mikulic 2010; Ramirez-Campillo et al. 2014"}],"advanceCriteria":"Short, consistent ground-contact times across sets; no soreness beyond 48 hours."},{"phase":4,"name":"Back to Sport","durationWeeksMin":4,"durationWeeksMax":8,"daysPerWeek":3,"exercises":[{"name":"Metronome-paced cadence cueing in runs","sets":4,"reps":"100-150m repeats at +3-5% cadence","cue":"Light quick feet in time with the cue, carried into normal strides","rationale":"Applies the timing lever to real running once reactive capacity/strength are established. No dedicated running-economy cadence-cueing citation exists in the source set — sequenced per general guidance, gap flagged.","sourceCitation":"General sequencing guidance, no specific RE-cadence-cueing citation found"},{"name":"Maintenance low-dose plyometrics","sets":2,"reps":"15-20s or 20m","cue":"Same quality as Phase 1","rationale":"Preserves gains during full return to training.","sourceCitation":"Markovic & Mikulic 2010, maintenance dosing"}],"advanceCriteria":"Full volume resumed with cadence cueing retained without conscious focus; periodically re-measure vertical oscillation."}]'),
('drill-banded-starts', 'Resisted banded starts', 'Loaded acceleration drill to shorten ground-contact time', 'https://cdn.stride.ai/drills/banded-starts.mp4', '["Lean into the band 45°","Powerful triple extension","Punch the ground and get off it fast"]', '["hamstring_strain","achilles_injury"]', '["contact_time_ms"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":3,"exercises":[{"name":"Pogo hops / ankle stiffness drill","sets":4,"reps":"15-20","cue":"Not targeting a specific contact-time number yet — focus on rhythm and quiet landings","rationale":"Lowest-impact entry, doubles as tendon-capacity foundation for later reactive work.","sourceCitation":"Pogo hop dosing; tendon-capacity-first sequencing principle"}],"advanceCriteria":"Full volume pain-free with consistent rhythm, no Achilles irritation."},{"phase":2,"name":"Strength","durationWeeksMin":3,"durationWeeksMax":5,"daysPerWeek":3,"exercises":[{"name":"Bounding (single/alternate-leg)","sets":5,"reps":"20-30m","cue":"Emphasize horizontal drive and deliberately longer, more forceful contacts — this is correct for acceleration mechanics, not a fault","rationale":"Builds leg-spring stiffness while reinforcing acceleration-phase mechanics as a distinct pattern.","sourceCitation":"Bounding dosing; acceleration-phase mechanics principle"},{"name":"Resisted sled sprints (10-20% BM, light-moderate)","sets":5,"reps":"15-20m","cue":"Contacts will run longer and flatter than max-velocity targets — expected and correct here","rationale":"Light load specifically dosed for contact-time/RSI development while naturally training acceleration-phase mechanics.","sourceCitation":"Light sled-sprint dosing for RSI goals, not heavier acceleration-strength loads"}],"advanceCriteria":"Consistent bounding rhythm and sled technique with no mechanical breakdown or tendon symptoms."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":3,"durationWeeksMax":5,"daysPerWeek":3,"exercises":[{"name":"Depth (drop) jumps","sets":4,"reps":"5-8","cue":"Individualize drop height for optimal RSI — this is where the 80-140ms band is most directly applicable (max-velocity-style stiffness)","rationale":"Highest-intensity reactive stimulus, only after tendon-capacity and mechanics base is established.","sourceCitation":"Depth-jump RSI dosing, sequenced after Phase 1-2"}],"advanceCriteria":"Stable or improving RSI at individualized drop height, no tendon symptoms."},{"phase":4,"name":"Back to Sport","durationWeeksMin":2,"durationWeeksMax":4,"daysPerWeek":2,"exercises":[{"name":"Pogo hops (maintenance)","sets":2,"reps":"15-20","cue":"Supports max-velocity-phase ankle stiffness, where 80-140ms remains the reference target","rationale":"Sustains tendon-capacity and stiffness gains through return to sport.","sourceCitation":"Maintenance dosing"},{"name":"Bounding (maintenance/integration)","sets":3,"reps":"20-30m","cue":"Elite acceleration contacts of 150-165ms are normal here — do not chase the shorter max-velocity target during this portion of training","rationale":"Maintains acceleration-phase mechanics distinctly from max-velocity targets.","sourceCitation":"Phase-specific maintenance dosing"}],"advanceCriteria":"Contact-time appropriate to each sprint phase (~150-165ms acceleration vs ~80-140ms max-velocity) across in-season training."}]'),
('drill-metronome', 'Metronome cadence intervals', 'Cadence-matching drill to raise step frequency toward the efficient range', 'https://cdn.stride.ai/drills/metronome.mp4', '["Match your footfalls to the beat","Quick, light steps","Relax at speed"]', '[]', '["cadence_spm"]', '[{"phase":1,"name":"Stability","durationWeeksMin":2,"durationWeeksMax":3,"daysPerWeek":2,"exercises":[{"name":"Nordic hamstring curl (low-volume)","sets":2,"reps":"4","cue":"Control the descent, quality over depth","rationale":"Baseline eccentric tolerance targeting the well-established late-swing mechanism, minimal fatigue cost.","sourceCitation":"Presland et al. 2018: low-volume protocol equivalent gains to high-volume"}],"advanceCriteria":"Two weeks of 2x4 completed with no more than mild DOMS, full-ROM control."},{"phase":2,"name":"Strength","durationWeeksMin":8,"durationWeeksMax":10,"daysPerWeek":3,"exercises":[{"name":"Nordic hamstring curl (progressive)","sets":2,"reps":"6-15, building to 3x12-15 by week 10","cue":"Increase range/load gradually, prioritize slow eccentric control","rationale":"Evidence-based backbone for eccentric hamstring capacity; addresses the mechanism directly rather than the contested cadence-injury link.","sourceCitation":"Petersen et al. 2011 RCT: 60% injury reduction (soccer population, applied cautiously)"},{"name":"Metronome/auditory-paced turnover drill","sets":4,"reps":"30-40m, paced above current cadence","cue":"Match foot-strike timing to the cue, prioritize quick contact over stride length","rationale":"Trains the technical turnover pattern in parallel with strength work.","sourceCitation":"2025 PLOS ONE study on metronome-paced turnover"}],"advanceCriteria":"Nordic curl reaches 3x10+ controlled tempo; paced cadence held for full rep distance across 2 sessions."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":3,"durationWeeksMax":4,"daysPerWeek":2,"exercises":[{"name":"Mini-hurdle rapid-fire stepping","sets":10,"reps":"10 low hurdles","cue":"Fast, light contacts, minimize ground time","rationale":"Acute, reactive turnover stimulus with measured step-frequency/velocity gains.","sourceCitation":"Yoshimoto et al. 2016: +3.2% velocity, +3.3% step frequency (acute)"},{"name":"Flywheel eccentric hamstring curl (if available)","sets":3,"reps":"6-8","cue":"Actively brake the eccentric phase; only once Nordic curls are well-tolerated","rationale":"Optional advanced eccentric overload for athletes with established Nordic curl tolerance.","sourceCitation":"Advanced progression, requires prior tolerance"}],"advanceCriteria":"Consistent ground-contact rhythm, no hamstring tightness; flywheel work (if used) stable at 3x6-8."},{"phase":4,"name":"Back to Sport","durationWeeksMin":4,"durationWeeksMax":6,"daysPerWeek":2,"exercises":[{"name":"Nordic curl (maintenance)","sets":2,"reps":"4","cue":"Maintain, do not chase new progression","rationale":"Ongoing low-volume dosing preserves capacity through return to sport.","sourceCitation":"Presland et al. 2018, maintenance dosing"},{"name":"Metronome cueing integrated into sprint sessions","sets":1,"reps":"Embedded within regular sprint work","cue":"Periodic technical check-in, not a standalone drill","rationale":"Folds the pattern into real sprint practice for transfer to competition.","sourceCitation":"2025 PLOS ONE study"}],"advanceCriteria":"Sustains target cadence during full-speed sessions without cueing; maintenance Nordic dosing tolerated with no symptoms."}]'),
('drill-lateral-band', 'Lateral band walks + single-leg balance', 'Frontal-plane hip strengthening to stop the knee collapsing inward', 'https://cdn.stride.ai/drills/lateral-band.mp4', '["Drive the knee over the middle toe","Don''t let it cave inward","Equal reps each side"]', '["knee_pain"]', '["knee_valgus"]', '[{"phase":1,"name":"Stability","durationWeeksMin":1,"durationWeeksMax":2,"daysPerWeek":3,"exercises":[{"name":"Single-leg stance / step-down motor control","sets":3,"reps":"30-45s holds or 8-10 controlled reps/leg","cue":"Kneecap over 2nd toe, hips level","rationale":"Builds basic single-leg postural control — capacity-building, not itself a fix for valgus.","sourceCitation":"Foundational precursor to single-leg squat progression"},{"name":"Lateral band walks","sets":3,"reps":"15-20 steps/direction","cue":"Slight knee bend, no trunk lean, resist band pulling knee inward","rationale":"Supporting hip-abductor capacity work only — NOT expected to change running-gait valgus by itself (Snyder 2011).","sourceCitation":"Snyder 2011: strength improved, pain reduced, valgus angle unchanged"}],"advanceCriteria":"Pain-free single-leg stance/step-down with level pelvis; band walks with no compensatory lean."},{"phase":2,"name":"Strength","durationWeeksMin":3,"durationWeeksMax":4,"daysPerWeek":3,"exercises":[{"name":"Clamshells (progressing to Clam 4)","sets":3,"reps":"15-20/side","cue":"Rotate from the hip, pelvis stacked and still","rationale":"Evidence-based strengthening — builds capacity but supporting only, does not change running-gait valgus alone.","sourceCitation":"Supporting-only per Snyder 2011"},{"name":"Single-leg squat","sets":3,"reps":"8-10/leg","cue":"Track knee over foot, control descent, hips level","rationale":"Closed-chain bridge exercise, more transferable but still no guarantee of running-gait change on its own — builds the base gait retraining will leverage.","sourceCitation":"Willy & Davis 2011"}],"advanceCriteria":"Single-leg squat for full volume with maintained knee alignment and pelvic control."},{"phase":3,"name":"Plyometrics & Movement","durationWeeksMin":4,"durationWeeksMax":4,"daysPerWeek":2,"exercises":[{"name":"Real-time gait retraining — mirror + verbal cueing during running","sets":1,"reps":"8 sessions, 2x/week for 4 weeks, feedback progressively faded","cue":"Run tall, keep the knee tracking over the toes, avoid hip drop; cueing reduced session over session","rationale":"The primary, PROVEN intervention for running-gait knee valgus — this is where the actual correction happens per the evidence, not in the strength phases.","sourceCitation":"Willy, Scholz & Davis 2012, Clinical Biomechanics"},{"name":"Single-leg squat (maintenance)","sets":2,"reps":"8-10/leg","cue":"Maintain knee-over-foot alignment under fatigue","rationale":"Continued strength-base maintenance while gait retraining becomes the focus.","sourceCitation":"Willy & Davis 2011"}],"advanceCriteria":"Demonstrates reduced valgus/hip drop under faded (intermittent) cueing during running."},{"phase":4,"name":"Back to Sport","durationWeeksMin":3,"durationWeeksMax":6,"daysPerWeek":2,"exercises":[{"name":"Real-time gait retraining — advanced (video feedback or wearable haptic)","sets":1,"reps":"2-4+ weeks integrated into full running volume, feedback progressively faded toward independence","cue":"Video: review footage to self-correct. Haptic: respond to vibrotactile cue by correcting mid-stride.","rationale":"Consolidates the gait change into real training volume and unsupervised running.","sourceCitation":"Noehren, Scholz & Davis 2011; Sheerin et al. 2020 (haptic feedback: ~50% reduction in tibial acceleration)"}],"advanceCriteria":"Maintains corrected running pattern with feedback fully withdrawn across full training runs."}]'),
('drill-hip-hitch', 'Single-leg hip hitches', 'Hip-abductor control drill to keep the pelvis level in single-leg stance', 'https://cdn.stride.ai/drills/hip-hitch.mp4', '["Keep your hips level","Don''t let the free side drop","Control the movement, no momentum"]', '["hip_labrum_tear"]', '["pelvic_drop"]',
 '[
   {
