       {"name": "Single-leg bridge", "sets": 3, "reps": "10-15/side", "cue": "Squeeze the glute to lift hips level, avoid arching the low back; stop if pain exceeds 5/10 or flares the next day", "rationale": "Part of the same evidence-based protocol.", "sourceCitation": "Lashien et al. 2024; LEAP pain-cap guidance (<5/10 NRS, no next-day flare)"},
       {"name": "Side-lying hip abduction with internal rotation", "sets": 3, "reps": "10-15/side", "cue": "Rotate the top leg slightly inward, lift with control, keep hips stacked", "rationale": "Highest glute-med EMG activation among studied hip-abductor exercises.", "sourceCitation": "Lashien et al. 2024; Distefano LJ et al., J Orthop Sports Phys Ther 2009;39(7):532-540"},
       {"name": "Lateral step-up", "sets": 3, "reps": "10-15/side, bodyweight to lightly weighted", "cue": "Step up under control, knee tracking over the toes — regress step height if the knee caves in or the hip drops", "rationale": "Closed-chain functional loading matching the RCT''s weight-bearing pattern.", "sourceCitation": "Lashien et al. 2024"}
     ],
     "advanceCriteria": "Full session with clean form (no knee-cave, no hip-hitch compensation); 10-RM has measurably increased from week 3."
