       {"name": "Single-leg Romanian deadlift", "sets": 3, "reps": "8-10/side", "cue": "Hinge at the hip, keep the back leg and torso in one line, control the return to standing", "rationale": "Bridges isolated strength to running-relevant single-leg loading.", "sourceCitation": "Pipeline plan-agent synthesis — integrated single-leg loading category"},
       {"name": "Single-leg split squat", "sets": 3, "reps": "8-10/side", "cue": "Controlled descent, front knee tracks over the foot", "rationale": "Running-specific transfer loading.", "sourceCitation": "Pipeline plan-agent synthesis — integrated single-leg loading category"},
       {"name": "Low-amplitude plyometrics (pogo hops, small bounds)", "sets": 3, "reps": "6-8 x 10-15s, or 8-10/side", "cue": "Small, quick ground contacts — stiffness and rhythm, not height", "rationale": "Mimics actual running loading rates before full return to running.", "sourceCitation": "Pipeline plan-agent synthesis — running-specific transfer category"}
